import React, { useContext, useState } from 'react';
import Header from "./Header";
import { Classement } from "./Classement";
import { Matchs } from "./Matchs";
import { Row, Col } from 'reactstrap';
import Select from 'react-select';
import { DataContext } from '../context';

export const Recent = () => {
  const currentYear = new Date().getFullYear() - 1;
  const [choisi, setChoisi] = useState(currentYear)

  const contextData = useContext(DataContext);

  const liste = contextData.annees.map(item => ({ value: item, label: item }));
  return (
    <div className="Home">
      <Header />
      <div className="Recent">
        <div className="SelectSeason">
          Saison
          <Select searchable={true} options={liste} value={{ label: choisi, value: choisi }}
            onChange={e => setChoisi(parseInt(e.value, 10))} />
        </div>
        <div className="PhotoSection">
          <a href="https://photos.google.com/share/AF1QipN9oXQt8d-jIo3QumBCWs3dwWCxxUHKLhDli6GuDETZfN3I7579XNTlTCp1k6_LWQ?key=RGIyYjI4WkxlcnJoaE9hMl9kcXhZUFlCZm4tSFlR" >
            <img className="Photo" src="data:image/jpeg;base64," />
            <div className="title">Gloire à Lopette 2021</div>
          </a>
        </div>
      </div>
      <Row>
        <Col sm={6} xs={12}><Classement year={choisi} /></Col>
        <Col sm={6} xs={12}><Matchs year={choisi} /></Col>
      </Row>
    </div>
  )
}